package ke.co.kais.masterai;
import android.app.Activity;import android.os.Bundle;import android.webkit.WebView;import android.webkit.WebViewClient;import android.webkit.WebSettings;
public class MainActivity extends Activity { private static final String WAR_ROOM="https://ma-aips-ai.hatchable.site/ceo.html"; private WebView web; @Override public void onCreate(Bundle state){super.onCreate(state);web=new WebView(this);WebSettings s=web.getSettings();s.setJavaScriptEnabled(true);s.setDomStorageEnabled(true);s.setSupportZoom(false);s.setBuiltInZoomControls(false);web.setWebViewClient(new WebViewClient());web.loadUrl(WAR_ROOM);setContentView(web);} @Override public void onBackPressed(){if(web.canGoBack())web.goBack();else super.onBackPressed();}}